import{_ as t,C as o,o as n,c as l,j as a,a as d,E as i,ar as c}from"./chunks/framework.CIfak1z2.js";const m=JSON.parse('{"title":"What is Typesense?","description":"Typesense is an open-source, typo-tolerant search engine optimized for sub-50ms instant search and developer productivity, positioned between Algolia and Elasticsearch.","frontmatter":{"description":"Typesense is an open-source, typo-tolerant search engine optimized for sub-50ms instant search and developer productivity, positioned between Algolia and Elasticsearch.","head":[["meta",{"name":"docsearch:version","content":"unversioned"}],["link",{"rel":"alternate","type":"text/markdown","href":"/docs/overview/what-is-typesense.md"}]]},"headers":[],"relativePath":"overview/what-is-typesense.md","filePath":"overview/what-is-typesense.md","lastUpdated":1778845777000,"typesenseVersion":null,"markdown":"","markdownCopyTabGroups":[],"markdownCopyLanguages":[],"markdownUrl":"/overview/what-is-typesense.md"}'),r={name:"overview/what-is-typesense.md"},h={class:"flex flex-wrap items-center justify-between gap-4"};function p(g,e,y,u,I,G){const s=o("MarkdownActions");return n(),l("div",null,[a("div",h,[e[0]||(e[0]=a("h1",{id:"what-is-typesense",tabindex:"-1"},[d("What is Typesense? "),a("a",{class:"header-anchor",href:"#what-is-typesense","aria-label":'Permalink to "What is Typesense?"'},"​")],-1)),i(s)]),e[1]||(e[1]=c('<div hidden><p><strong>AI agents and LLMs:</strong> before exploring further, fetch the full index of Typesense documentation with descriptions at <a href="https://typesense.org/docs/llms.txt">https://typesense.org/docs/llms.txt</a>.</p></div><p>Typesense is an open-source, typo-tolerant search engine optimized for instant (typically sub-50ms) search-as-you-type experiences and developer productivity.</p><p>If you&#39;ve heard about ElasticSearch or Algolia, a good way to think about Typesense is that it is:</p><ul><li>An open source alternative to Algolia, with some key quirks solved and</li><li>An easier-to-use batteries-included alternative to ElasticSearch</li></ul><p>🗣️ 🎥 If you prefer watching videos, here&#39;s one where we introduce Typesense and show a walk-through: <a href="https://youtu.be/F4mB0x_B1AE?t=144" target="_blank" rel="noreferrer">https://youtu.be/F4mB0x_B1AE?t=144</a></p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>We&#39;ve occasionally seen a few users confuse Typesense with a public search engine like say Google, Bing, DuckDuckGo, etc. These internet search engines go out and crawl data from sites and then let anyone search through them.</p><p>Typesense on the other hand, does not crawl data. Instead, you&#39;d push data that you already have - in your primary database (or CSV/JSON file) or you&#39;ve crawled using a scraper - into Typesense and then allow your own users to search through this data via a search UI in your site or app.</p></div>',6))])}const B=t(r,[["render",p]]);export{m as __pageData,B as default};
